import sys

def main():
    data = sys.stdin.read().split()
    ptr = 0
    n = int(data[ptr])
    ptr += 1

    if n <= 0:
        arr = []
    else:
        arr = []
        for _ in range(n):
            arr.append(int(data[ptr]))
            ptr += 1

    index = int(data[ptr])

    length = len(arr)
    if index < 0 or index >= length:
        print(f"ArrayIndexOutOfBoundsException: Index {index} out of bounds for length {length}")
    else:
        print(f"Element at index {index}: {arr[index]}")

if __name__ == "__main__":
    main()
